import SwiftUI

@main
struct BeaverAgentApp: App {
    @State private var session = AgentSession()
    @State private var sheet: AppSheet?
    @AppStorage(SettingsKey.serverURL) private var serverURL = ""
    @AppStorage(SettingsKey.token) private var token = ""
    @AppStorage(SettingsKey.useFixtures) private var useFixtures = true
    @AppStorage(SettingsKey.appearance) private var appearance = Appearance.system
    @AppStorage(SettingsKey.largeText) private var largeText = false
    @AppStorage(SettingsKey.handsFree) private var handsFree = false
    @Environment(\.scenePhase) private var scenePhase

    var body: some Scene {
        WindowGroup {
            ContentView(session: session, sheet: $sheet)
                .sheet(item: $sheet) { sheet in
                    switch sheet {
                    case .settings:
                        SettingsSheet(connection: session.connection)
                    case .debug:
                        DebugSheet(
                            isFixtureMode: session.connection == .fixtures,
                            ask: session.ask,
                            simulateScreenshot: session.simulateScreenshot
                        )
                        .presentationDetents([.medium, .large])
                    }
                }
                .preferredColorScheme(appearance.colorScheme)
                .environment(\.typeScale, typeScale)
                .task {
                    applySettings()
                    DemoLaunch.apply(to: session, sheet: $sheet)
                }
                .onChange(of: settingsKey) { applySettings() }
                .onChange(of: largeText, initial: true) { session.typeScale = typeScale }
                .onChange(of: scenePhase) { _, phase in
                    if phase == .active { session.appBecameActive() }
                }
        }
    }

    private var typeScale: TypeScale { largeText ? .large : .regular }

    private var settingsKey: String { "\(useFixtures)|\(serverURL)|\(token)|\(handsFree)" }

    private func applySettings() {
        session.configure(useFixtures: useFixtures, serverURL: serverURL, token: token, handsFree: handsFree)
    }
}

/// Launch arguments for rehearsals and screenshots, e.g.
/// `-demoScene searching`, `-demoSheet debug`, `-demoAsk "Can I make it?"`.
/// Live server only: `-demoHold 3` holds the orb for 3 s once connected, `-demoTapAt 9`
/// taps it 9 s after connecting; with `-micFile` this drives the voice path without a finger.
@MainActor
enum DemoLaunch {
    static func apply(to session: AgentSession, sheet: Binding<AppSheet?>) {
        let defaults = UserDefaults.standard
        if let scene = defaults.string(forKey: "demoScene") {
            play(scene, on: session)
        }
        if let name = defaults.string(forKey: "demoSheet"), let value = AppSheet(rawValue: name) {
            sheet.wrappedValue = value
        }
        if let question = defaults.string(forKey: "demoAsk") {
            Task {
                try? await Task.sleep(for: .seconds(2))
                session.ask(question)
            }
        }
        let hold = defaults.double(forKey: "demoHold")
        let tapAt = defaults.double(forKey: "demoTapAt")
        if hold > 0 || tapAt > 0 {
            Task {
                while session.connection != .live { try? await Task.sleep(for: .milliseconds(100)) }
                if hold > 0 {
                    session.orbPressBegan()
                    try? await Task.sleep(for: .seconds(hold))
                    session.orbPressEnded()
                }
                if tapAt > hold {
                    try? await Task.sleep(for: .seconds(tapAt - hold))
                    session.orbPressBegan()
                    try? await Task.sleep(for: .milliseconds(80))
                    session.orbPressEnded()
                }
            }
        }
    }

    private static func play(_ scene: String, on session: AgentSession) {
        let question = "Can I make it to dinner in Bern?"
        switch scene {
        case "listening":
            session.handle(.state(.listening, label: nil))
        case "thinking":
            session.handle(.transcript(question))
            session.handle(.state(.thinking, label: nil))
        case "searching":
            session.handle(.transcript(question))
            session.handle(.state(.thinking, label: nil))
            session.handle(.state(.searching, label: "Checking trains…"))
        case "speaking", "reply", "kinds":
            let turn = scene == "kinds" ? Fixtures.otherKinds : Fixtures.demo
            session.handle(.transcript(scene == "kinds" ? "What's coming up this week?" : question))
            session.handle(.state(.thinking, label: nil))
            session.handle(.state(.searching, label: turn.label))
            turn.frames.forEach(session.receive)
            session.handle(.state(scene == "speaking" ? .speaking : .idle, label: nil))
        case "screen":
            session.simulateScreenshot()
        case "error":
            session.handle(.transcript(question))
            session.handle(.error("Sorry, something went wrong."))
        default:
            break
        }
    }
}
import A2UISwiftCore
import A2UISwiftUI
import Foundation
import Observation

/// Everything the one screen shows, driven by server frames (or fixture frames).
/// Only the latest turn is kept: there is no chat thread.
@MainActor
@Observable
final class AgentSession {
    enum Connection: Equatable {
        case fixtures
        case connecting
        case live
        case offline(String)
    }

    struct ScreenNotice: Equatable {
        let id = UUID()
        let summary: String?
    }

    /// How long the screen chip stays up (WP1 task 8).
    static let screenChipLifetime: Duration = .seconds(120)

    /// What the orb shows: the server's state, but `speaking` while TTS audio is still
    /// queued, even after the server sent `state: idle` (contracts § WebSocket).
    var orb: OrbState {
        if isPlaying && (serverState == .idle || serverState == .speaking) { return .speaking }
        return serverState
    }
    private(set) var serverState: OrbState = .idle
    /// TTS audio is queued or playing on the speaker.
    private(set) var isPlaying = false
    /// Hands-free mode (settings): the mic streams the whole time and nobody holds the orb.
    private(set) var handsFree = false
    private(set) var label: String?
    private(set) var transcript: String?
    private(set) var reply: Reply?
    /// Tool steps of the current turn, e.g. "Checking trains…", shown as a one-line trail.
    private(set) var steps: [String] = []
    private(set) var surfaces: [SurfaceViewModel] = []
    private(set) var screen: ScreenNotice?
    private(set) var errorMessage: String?
    private(set) var connection: Connection = .fixtures

    /// Card text follows the app's type scale ("Large text" in settings).
    var typeScale: TypeScale = .regular {
        didSet { surfaces.forEach { $0.applyAppStyle(typeScale) } }
    }

    /// A touch on the orb shorter than this is a tap (interrupt), longer is push-to-talk.
    static let holdThreshold: Duration = .milliseconds(250)

    private enum Press {
        case none
        /// Finger down, tap or hold not known yet; mic chunks wait here.
        case deciding(interrupts: Bool, chunks: [String])
        case talking(sentAudio: Bool)
    }

    private let client = WebSocketClient()
    private let voice = VoiceIO()
    private var press = Press.none
    private var pressDecision: Task<Void, Never>?
    /// After an interrupt, the cancelled turn's `audio` frames are dropped until the next turn.
    private var droppingAudio = false
    private var fixtureTurn: Task<Void, Never>?
    private var screenExpiry: Task<Void, Never>?

    init() {
        voice.onChunk = { [weak self] in self?.micChunk($0) }
        voice.onPlayingChange = { [weak self] in self?.isPlaying = $0 }
        voice.onProblem = { [weak self] in self?.errorMessage = $0 }
        client.onMessage = { [weak self] in self?.handle($0) }
        client.onStatus = { [weak self] status in
            guard let self, connection != .fixtures else { return }
            if status != .connected && status != .connecting { connectionLost() }
            switch status {
            case .disconnected: connection = .offline("Not connected")
            case .connecting: if connection != .live { connection = .connecting }
            case .connected: connection = .live
            case .failed(let reason): connection = .offline(reason)
            }
        }
    }

    // MARK: - Connection

    /// Applies the settings: fixture mode, or the live server at `serverURL`.
    func configure(useFixtures: Bool, serverURL: String, token: String, handsFree: Bool) {
        cancelPress()
        voice.stopPlayback()
        guard !useFixtures, let url = WebSocketClient.endpointURL(from: serverURL) else {
            client.disconnect()
            voice.stop()
            connection = .fixtures
            self.handsFree = false
            return
        }
        self.handsFree = handsFree
        connection = .connecting
        client.connect(url: url, token: token, mode: handsFree ? .handsfree : .ptt)
        voice.start()
    }

    func appBecameActive() {
        client.ensureConnected()
        if connection != .fixtures { voice.resume() }
    }

    // MARK: - Talking

    /// Finger down on the orb. A tap stops the mascot (`interrupt`); holding is push-to-talk:
    /// `audio` while held, `audio_end` on release. Either way playback stops at once.
    func orbPressBegan() {
        guard connection == .live, case .none = press else { return }
        let interrupts = orb == .speaking
        if interrupts { stopSpeaking() }
        if handsFree || !voice.hasMic {
            if interrupts { client.send(.interrupt) }
            return
        }
        press = .deciding(interrupts: interrupts, chunks: [])
        pressDecision = Task { [weak self] in
            try? await Task.sleep(for: Self.holdThreshold)
            guard !Task.isCancelled else { return }
            self?.startTalking()
        }
    }

    func orbPressEnded() {
        pressDecision?.cancel()
        switch press {
        case .none:
            return
        case .deciding(let interrupts, _):
            if interrupts { client.send(.interrupt) }
        case .talking(let sentAudio):
            if sentAudio {
                client.send(.audioEnd)
            } else {
                handle(.state(.idle, label: nil))  // released before the first chunk: the server heard nothing
            }
        }
        press = .none
    }

    /// The touch became a hold: send what the mic heard since the finger went down, then stream.
    private func startTalking() {
        guard case .deciding(_, let chunks) = press else { return }
        press = .talking(sentAudio: !chunks.isEmpty)
        stopSpeaking()  // the first `audio` frame cancels the running turn on the server
        handle(.state(.listening, label: nil))
        chunks.forEach { client.send(.audio($0)) }
    }

    private func cancelPress() {
        pressDecision?.cancel()
        press = .none
    }

    private func micChunk(_ chunk: String) {
        guard connection == .live else { return }
        if handsFree {
            client.send(.audio(chunk))  // also while the mascot speaks: voice processing cancels the echo
            return
        }
        switch press {
        case .none: break
        case .deciding(let interrupts, let chunks): press = .deciding(interrupts: interrupts, chunks: chunks + [chunk])
        case .talking:
            press = .talking(sentAudio: true)
            client.send(.audio(chunk))
        }
    }

    /// The socket dropped: a turn in flight will never finish.
    private func connectionLost() {
        cancelPress()
        stopSpeaking()
        serverState = .idle
        label = nil
    }

    /// Stops the mascot now, without waiting for the server, and drops the rest of its audio.
    private func stopSpeaking() {
        voice.stopPlayback()
        droppingAudio = true
    }

    // MARK: - Asking

    /// A typed question (debug field or intent chip): `text` on the wire.
    func ask(_ question: String) {
        let question = question.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !question.isEmpty else { return }
        transcript = question
        if connection == .fixtures {
            runFixtureTurn(question)
        } else {
            stopSpeaking()  // a `text` cancels the running turn
            client.send(.text(question))
        }
    }

    /// Fixture mode only: what the server sends after the iPhone Shortcut posts a screenshot.
    func simulateScreenshot() {
        receive(Fixtures.screenOK)
    }

    // MARK: - Server frames

    func handle(_ message: ServerMessage) {
        switch message {
        case .ready, .unknown:
            break
        case .audio(let data):
            if !droppingAudio { voice.play(base64: data) }
        case .audioEnd:
            if !droppingAudio { voice.endSpeech() }
        case .state(let state, let label):
            if state == .listening && serverState != .listening {
                stopSpeaking()  // hands-free: the user talks over the mascot
            }
            if state == .thinking {
                // Every turn starts with `thinking`, so a reply after this one is the new turn's,
                // not the cancelled turn's reply that crossed the interrupt on the wire.
                droppingAudio = false
            }
            if state == .thinking && serverState != .thinking && serverState != .searching {
                steps = []  // a new turn starts
                errorMessage = nil
            }
            if state == .searching, let label, steps.last != label {
                steps.append(label)
            }
            serverState = state
            self.label = label
        case .transcript(let text):
            transcript = text
        case .reply(let reply):
            voice.beginSpeech()
            self.reply = reply
            surfaces = []
            errorMessage = nil
        case .a2ui(let messages):
            surfaces = Self.surfaces(from: messages)
            surfaces.forEach { $0.applyAppStyle(typeScale) }
        case .screenOK(let summary):
            showScreen(ScreenNotice(summary: summary))
        case .error(let message):
            errorMessage = message
        }
    }

    /// Decodes one fixture frame through the same path as a live frame.
    func receive(_ frame: Data) {
        do {
            handle(try ServerMessage.decode(frame))
        } catch {
            print("fixture frame failed to decode: \(error)")
        }
    }

    /// One `SurfaceViewModel(catalog: basicCatalog)` per surface (contracts § A2UI).
    static func surfaces(from messages: [A2uiMessage]) -> [SurfaceViewModel] {
        var order: [String] = []
        var models: [String: SurfaceViewModel] = [:]
        for message in messages {
            let id = message.surfaceId
            if models[id] == nil {
                models[id] = SurfaceViewModel(catalog: basicCatalog)
                order.append(id)
            }
            let errors = models[id]?.processMessages([message]) ?? []
            for error in errors { print("a2ui \(id): \(error)") }
        }
        return order.compactMap { models[$0] }.filter { $0.componentTree != nil }
    }

    // MARK: - Private

    private func showScreen(_ notice: ScreenNotice) {
        screen = notice
        screenExpiry?.cancel()
        screenExpiry = Task { [weak self] in
            try? await Task.sleep(for: Self.screenChipLifetime)
            guard !Task.isCancelled, self?.screen?.id == notice.id else { return }
            self?.screen = nil
        }
    }

    /// Replays a fixture reply with the server's timing: thinking, a tool step, the
    /// reply and cards, then speaking until roughly when the spoken answer would end.
    private func runFixtureTurn(_ question: String) {
        fixtureTurn?.cancel()
        let turn = Fixtures.turn(for: question)
        fixtureTurn = Task { [weak self] in
            guard let self else { return }
            guard await fixtureStep(.thinking, wait: 0.9) else { return }
            guard await fixtureStep(.searching, turn.label, wait: 1.1) else { return }
            turn.frames.forEach(receive)
            let words = Double(reply?.say.split(separator: " ").count ?? 10)
            guard await fixtureStep(.speaking, wait: max(2, words * 0.32)) else { return }
            handle(.state(.idle, label: nil))
        }
    }

    private func fixtureStep(_ state: OrbState, _ label: String? = nil, wait seconds: Double) async -> Bool {
        handle(.state(state, label: label))
        try? await Task.sleep(for: .seconds(seconds))
        return !Task.isCancelled
    }
}

extension A2uiMessage {
    var surfaceId: String {
        switch self {
        case .createSurface(let payload): payload.surfaceId
        case .updateComponents(let payload): payload.surfaceId
        case .updateDataModel(let payload): payload.surfaceId
        case .deleteSurface(let payload): payload.surfaceId
        }
    }
}
import A2UISwiftCore
import Foundation

// Wire types for the WebSocket `/ws`, see docs/contracts.md § WebSocket.

enum OrbState: String, Codable, CaseIterable {
    case idle, listening, thinking, searching, speaking
}

/// One card from `reply.cards`. The app renders the `a2ui` messages built from these;
/// `raw` keeps the card's JSON so native fallback views can decode it their own way
/// (contracts § Cards: `.convertFromSnakeCase`, `.iso8601`).
struct CardPayload: Decodable, Equatable {
    let kind: String
    let raw: Data

    init(from decoder: Decoder) throws {
        let value = try JSONValue(from: decoder)
        guard case .object(let fields) = value, case .string(let kind)? = fields["kind"] else {
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "card without kind"))
        }
        self.kind = kind
        self.raw = try JSONEncoder().encode(value)
    }
}

struct Reply: Decodable, Equatable {
    let say: String
    let cards: [CardPayload]
}

enum ServerMessage {
    case ready
    case state(OrbState, label: String?)
    case transcript(String)
    case reply(Reply)
    case a2ui([A2uiMessage])
    /// Base64 PCM, contracts § Audio.
    case audio(String)
    case audioEnd
    case screenOK(summary: String?)
    case error(String)
    case unknown(String)

    /// Decodes one JSON text frame. Unknown `type`s are kept, not thrown, so a newer
    /// server never breaks the app.
    static func decode(_ data: Data) throws -> ServerMessage {
        let envelope = try JSONDecoder().decode(Envelope.self, from: data)
        let decoder = JSONDecoder()
        switch envelope.type {
        case "ready":
            return .ready
        case "state":
            let frame = try decoder.decode(StateFrame.self, from: data)
            return .state(OrbState(rawValue: frame.state) ?? .idle, label: frame.label)
        case "transcript":
            return .transcript(try decoder.decode(TextFrame.self, from: data).text)
        case "reply":
            return .reply(try decoder.decode(Reply.self, from: data))
        case "a2ui":
            // Plain decoder on purpose: A2UI keys are camelCase and data keys must stay untouched.
            return .a2ui(try decoder.decode(A2UIFrame.self, from: data).messages)
        case "audio":
            return .audio(try decoder.decode(AudioFrame.self, from: data).data)
        case "audio_end":
            return .audioEnd
        case "screen_ok":
            return .screenOK(summary: try decoder.decode(ScreenFrame.self, from: data).summary)
        case "error":
            return .error(try decoder.decode(ErrorFrame.self, from: data).message)
        default:
            return .unknown(envelope.type)
        }
    }

    private struct Envelope: Decodable { let type: String }
    private struct StateFrame: Decodable { let state: String; let label: String? }
    private struct TextFrame: Decodable { let text: String }
    private struct A2UIFrame: Decodable { let messages: [A2uiMessage] }
    private struct AudioFrame: Decodable { let data: String }
    private struct ScreenFrame: Decodable { let summary: String? }
    private struct ErrorFrame: Decodable { let message: String }
}

enum ClientMessage: Encodable {
    enum Mode: String { case ptt, handsfree }

    case hello(token: String, mode: Mode)
    case text(String)
    /// One 80 ms mic chunk, base64 PCM (contracts § Audio).
    case audio(String)
    /// Orb released (push-to-talk only).
    case audioEnd
    /// Tap while the mascot is talking.
    case interrupt

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: Key.self)
        switch self {
        case .hello(let token, let mode):
            try container.encode("hello", forKey: .type)
            try container.encode(token, forKey: .token)
            try container.encode(mode.rawValue, forKey: .mode)
        case .text(let text):
            try container.encode("text", forKey: .type)
            try container.encode(text, forKey: .text)
        case .audio(let data):
            try container.encode("audio", forKey: .type)
            try container.encode(data, forKey: .data)
        case .audioEnd:
            try container.encode("audio_end", forKey: .type)
        case .interrupt:
            try container.encode("interrupt", forKey: .type)
        }
    }

    private enum Key: String, CodingKey { case type, token, mode, text, data }
}

/// Minimal JSON tree, used to keep card JSON intact.
enum JSONValue: Codable, Equatable {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() {
            self = .null
        } else if let value = try? container.decode(Bool.self) {
            self = .bool(value)
        } else if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if let value = try? container.decode(String.self) {
            self = .string(value)
        } else if let value = try? container.decode([JSONValue].self) {
            self = .array(value)
        } else {
            self = .object(try container.decode([String: JSONValue].self))
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .null: try container.encodeNil()
        case .bool(let value): try container.encode(value)
        case .number(let value): try container.encode(value)
        case .string(let value): try container.encode(value)
        case .array(let value): try container.encode(value)
        case .object(let value): try container.encode(value)
        }
    }
}

