        switch self {
        case .train(let card):
            try card.encode(to: encoder)
        case .conflict(let card):
            try card.encode(to: encoder)
        case .event(let card):
            try card.encode(to: encoder)
        case .flight(let card):
            try card.encode(to: encoder)
        }
    }
}

