import ActivityKit
import Foundation

/// The hands-free session's Live Activity, shared by the app (which starts, updates and ends it)
/// and the `OrbActivity` widget extension (which draws it). ActivityKit carries the content
/// state from the app to the extension, so the two targets need no App Group.
struct OrbActivityAttributes: ActivityAttributes {
    /// Kept small: ActivityKit caps the encoded state at 4 KB.
    struct ContentState: Codable, Hashable {
        var phase: OrbPhase
        /// The visible status label, always shown (brand kit: status labels are mandatory).
        var status: String
        /// The reply's `say` once answered, the question while working, the problem on error.
        var line: String?
        /// The card worth a glance: the first train or flight, otherwise the first card.
        var card: CardGlance?
        /// A conflict card's verdict in one line, when the reply has one besides `card`.
        var verdict: CardGlance?
    }
}

/// The orb states of docs/brand-kit/README.md that a hands-free session goes through.
enum OrbPhase: String, Codable, Hashable {
    case ready, listening, thinking, acting, done, error

    var defaultStatus: String {
        switch self {
        case .ready: "Ready"
        case .listening: "Listening…"
        case .thinking: "Thinking…"
        case .acting: "Acting…"
        case .done: "Done"
        case .error: "Something went wrong"
        }
    }
}

/// One card from `reply.cards` (contracts § Cards), reduced to what fits the Dynamic Island.
/// Times are already formatted `HH:MM` in Europe/Zurich by the app.
struct CardGlance: Codable, Hashable {
    enum Kind: String, Codable, Hashable { case train, conflict, event, flight }

    var kind: Kind
    /// The hero: the departure time for train and flight, the verdict for conflict, the title for event.
    var title: String
    /// One detail line: "IC 8 · Platform 31", "Dinner in Bern · 19:00", "Sat 17 Oct · 09:00".
    var detail: String
    /// Optional second line, e.g. "Zürich HB → Bern · 18:58".
    var note: String?
    /// At most about five characters, for the compact Dynamic Island: "18:01", "Fits".
    var compact: String

    /// SF Symbol for the kind; text always sits next to it, never color alone.
    var symbol: String {
        switch kind {
        case .train: "tram.fill"
        case .flight: "airplane"
        case .event: "calendar"
        case .conflict: "calendar.badge.clock"
        }
    }
}

import SwiftUI

/// The brand orb (docs/brand-kit/README.md: the thinking-orbs 0.3.2 `breathing` ring) as one
/// still frame. Live Activities can't run a render loop, so this draws the frame the library
/// itself shows for reduced motion (time 0.6), with the library's 20 pt inline preset and the
/// state's `dotSize`. Ported from the library's ring geometry in docs/brand-kit/index.html.
struct OrbRing: View {
    var phase: OrbPhase
    var dark: Bool
    var size: CGFloat = 20

    var body: some View {
        Canvas { context, _ in
            for dot in Self.dots(size: size, dotSize: phase.dotSize) {
                let rect = CGRect(x: dot.x - dot.r, y: dot.y - dot.r, width: dot.r * 2, height: dot.r * 2)
                let gray = min(1, max(0, dark ? 1 - dot.white : dot.white))
                context.fill(Path(ellipseIn: rect), with: .color(Color(white: gray, opacity: dot.alpha)))
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }

    private struct Dot {
        var x, y, z, r, white, alpha: Double
    }

    /// The library's `ring` frame: a face-on band of dot lanes, tilted 0.3 rad, nearer dots
    /// bigger, darker and more opaque.
    private static func dots(size: CGFloat, dotSize: Double, time t: Double = 0.6) -> [Dot] {
        // Size presets from the library: dot count and dot size scale with the canvas.
        let (count, sizeMul, bandMul, wobMul) = size < 42 ? (0.028, 1.622, 3.968, 0.565) : (0.25, 0.956, 3.627, 0.368)
        let lanes = max(2, (5 * count.squareRoot()).rounded())
        let segs = Int(max(2, (88 * count.squareRoot()).rounded()))
        let rBase = 1.1 * sizeMul * dotSize
        let rDepth = 1.7 * sizeMul * dotSize
        let rMin = 0.3

        let half = Double(size) / 2
        let radius = half * 0.78
        let scale = pow(Double(size) / 300, 0.6)
        let tilt = 0.3
        func project(_ x: Double, _ y: Double, _ z: Double) -> (Double, Double, Double) {
            let up = y * cos(tilt) - z * sin(tilt)
            let depth = y * sin(tilt) + z * cos(tilt)
            return (half + x, half - up, depth)
        }

        let face = -tilt
        let wobble = 0.23 * wobMul
        let ringRadius = radius / (1 + 0.85 * wobble)
        let bands = Int(max(1, (lanes * bandMul).rounded()))
        let middle = Double(bands - 1) / 2

        var dots: [Dot] = []
        for lane in 0..<bands {
            let offset = (Double(lane) - middle) * 0.075
            let edge = abs(Double(lane) - middle) / max(1, middle)
            for seg in 0..<segs {
                let angle = Double(seg) / Double(segs) * 2 * .pi
                let wave = (0.16 * sin(angle * 3 - t * 1.7 + Double(lane) * 0.22) + 0.07 * sin(angle * 5 + t * 1.1)) * wobMul
                let qx = cos(angle)
                let qy = cos(face) * sin(angle) - sin(face) * offset
                let qz = sin(face) * sin(angle) + cos(face) * offset
                let length = (qx * qx + qy * qy + qz * qz).squareRoot()
                let reach = ringRadius * (1 + wave)
                let (x, y, z) = project(qx / length * reach, qy / length * reach, qz / length * reach)
                let near = (z / radius + 1) / 2
                let alpha = 0.4 + 0.6 * near
                guard alpha >= 0.02 else { continue }
                dots.append(Dot(
                    x: x, y: y, z: z,
                    r: max(rMin, (rBase + rDepth * near) * (1 - 0.25 * edge) * scale),
                    white: 0.52 - 0.44 * near + 0.18 * edge,
                    alpha: alpha
                ))
            }
        }
        return dots.sorted { $0.z < $1.z }
    }
}

extension OrbPhase {
    /// The library's `dotSize` per state (docs/brand-kit/OrbsIndicator.tsx).
    var dotSize: Double {
        switch self {
        case .listening, .thinking: 1
        case .acting: 1.15
        case .ready, .done, .error: 0.8
        }
    }
}

import ActivityKit
import SwiftUI
import WidgetKit

/// The hands-free Live Activity: the orb's state, the reply's `say` line and the card worth a
/// glance, on the lock screen and in the Dynamic Island. Monochrome per docs/brand-kit: the
/// system's own glass and island backgrounds, ink from the kit's tokens, no gradients.
struct OrbLiveActivity: Widget {
    var body: some WidgetConfiguration {
        ActivityConfiguration(for: OrbActivityAttributes.self) { context in
            LockScreenView(state: context.state)
                .activitySystemActionForegroundColor(Ink.text(dark: true))
        } dynamicIsland: { context in
            let state = context.state
            return DynamicIsland {
                DynamicIslandExpandedRegion(.leading) {
                    HStack(spacing: 8) {
                        OrbRing(phase: state.phase, dark: true)
                        StatusLabel(state: state, dark: true)
                    }
                    .padding(.leading, 4)
                    .padding(.top, 4)
                }
                DynamicIslandExpandedRegion(.trailing) {
                    if let card = state.card, card.kind.isTimed {
                        Text(card.title)
                            .font(.system(size: 28, weight: .medium).monospacedDigit())
                            .tracking(-0.7)
                            .foregroundStyle(Ink.text(dark: true))
                            .padding(.trailing, 4)
                    }
                }
                DynamicIslandExpandedRegion(.bottom) {
                    ExpandedDetails(state: state)
                        .padding(.horizontal, 4)
                        .padding(.bottom, 4)
                }
            } compactLeading: {
                OrbRing(phase: state.phase, dark: true)
            } compactTrailing: {
                Text(state.compactText)
                    .font(.system(size: 14, weight: .semibold).monospacedDigit())
                    .foregroundStyle(Ink.text(dark: true))
                    .lineLimit(1)
                    .minimumScaleFactor(0.8)
            } minimal: {
                OrbRing(phase: state.phase, dark: true)
            }
            .keylineTint(Ink.text(dark: true))
        }
    }
}

// MARK: - Lock screen

private struct LockScreenView: View {
    let state: OrbActivityAttributes.ContentState
    @Environment(\.colorScheme) private var scheme

    var body: some View {
        let dark = scheme == .dark
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                OrbRing(phase: state.phase, dark: dark)
                StatusLabel(state: state, dark: dark)
                Spacer(minLength: 8)
                Text("Orb Agent")
                    .font(.system(size: 12, weight: .medium))
                    .foregroundStyle(Ink.secondary(dark: dark))
            }
            if let line = state.line {
                Text(line)
                    .font(.system(size: 15))
                    .foregroundStyle(Ink.text(dark: dark))
                    .lineLimit(3)
                    .fixedSize(horizontal: false, vertical: true)
            }
            if let card = state.card {
                CardRow(card: card, dark: dark, framed: true)
            }
            if let verdict = state.verdict {
                CardRow(card: verdict, dark: dark, framed: false)
            }
        }
        .padding(20)
    }
}

// MARK: - Dynamic Island, expanded

private struct ExpandedDetails: View {
    let state: OrbActivityAttributes.ContentState

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            if let card = state.card {
                if card.kind.isTimed {
                    // The time is the trailing hero; its line and platform go first here.
                    DetailLine(symbol: card.symbol, text: [card.detail, card.note].compactMap { $0 }.joined(separator: " · "), dark: true)
                } else {
                    CardRow(card: card, dark: true, framed: false)
                }
            }
            if let line = state.line {
                Text(line)
                    .font(.system(size: 15))
                    .foregroundStyle(Ink.text(dark: true))
                    .lineLimit(2)
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
            if let verdict = state.verdict {
                CardRow(card: verdict, dark: true, framed: false)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }
}

// MARK: - Pieces

/// The orb's status label, with a check for Done and a warning for errors (brand kit: text
/// and icons for status, never color alone).
private struct StatusLabel: View {
    let state: OrbActivityAttributes.ContentState
    let dark: Bool

    var body: some View {
        HStack(spacing: 4) {
